// Offline birth-place list, generated by packages/cities (GeoNames data, CC BY 4.0; time zones via tz-lookup, CC0).
// US: every place with 1,000+ people. World: cities with 100,000+ people. Rows are sorted by population.
import data from './cities.json';

export interface City { name: string; region: string; country: string; lat: number; lon: number; tz: string }

type Row = [string, string, string, number, number, number];
const rows = data.rows as Row[];
const tzs = data.tzs as string[];
const countries = data.countries as Record<string, string>;

const norm = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const index = rows.map((r) => norm(r[0]));

const toCity = (r: Row): City => ({ name: r[0], region: r[1], country: countries[r[2]] ?? r[2], lat: r[3], lon: r[4], tz: tzs[r[5]] });

export const placeLabel = (c: City) => [c.name, c.region, c.country].filter(Boolean).join(', ');

export function searchCities(q: string, limit = 6): City[] {
  const n = norm(q.trim());
  if (n.length < 2) return [];
  const starts: number[] = [], contains: number[] = [];
  for (let i = 0; i < index.length && starts.length < limit; i++) {
    if (index[i].startsWith(n)) starts.push(i);
    else if (contains.length < limit && index[i].includes(n)) contains.push(i);
  }
  return [...starts, ...contains].slice(0, limit).map((i) => toCity(rows[i]));
}
